import {exportBackup,parseBackup,restoreBackup} from './backup-core.js';
export function installBackup({pause,beforeExport,reload}){
 const storage={getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)};
 const dialog=document.createElement('dialog');dialog.id='backupMenu';dialog.setAttribute('aria-labelledby','backupTitle');const title=document.createElement('h2');title.id='backupTitle';title.textContent='Back up your park progress';const info=document.createElement('p');info.textContent='Download a file with your points, keepsakes, home choices and settings. Keep it to restore this visit in another browser.';const message=document.createElement('p');message.id='backupStatus';message.setAttribute('role','status');const download=document.createElement('button');download.id='backupDownload';download.textContent='Download backup';const label=document.createElement('label');label.textContent='Choose a backup to restore';label.htmlFor='backupFile';const file=document.createElement('input');file.id='backupFile';file.type='file';file.accept='.json,application/json';const restore=document.createElement('button');restore.id='backupRestore';restore.textContent='Replace my progress and reload';restore.hidden=true;const close=document.createElement('button');close.id='backupClose';close.textContent='Cancel / close';close.onclick=()=>{pending=null;restore.hidden=true;dialog.close();};dialog.append(title,info,download,label,file,message,restore,close);document.body.append(dialog);
 const current=document.createElement('p');current.id='backupCurrent';current.setAttribute('aria-live','polite');dialog.append(current);let currentSummary=null;
 const summaryText=s=>s.points+' points · '+s.keepsakes+' keepsakes · Home: '+s.home;
 function showCurrent(){try{currentSummary=parseBackup(exportBackup(storage)).summary;current.textContent='Current browser: '+summaryText(currentSummary)+'.';}catch{currentSummary=null;current.textContent='Current browser progress could not be read. Download a backup if possible before replacing it.';}}
 const css=document.createElement('link');css.rel='stylesheet';css.href='backup.css';document.head.append(css);const nav=document.createElement('button');nav.id='backupButton';nav.textContent='Back up progress';document.querySelector('nav').append(nav);let pending=null,readVersion=0;
 dialog.replaceChildren(title,info,current,download,label,file,message,restore,close);
 dialog.addEventListener('close',()=>{readVersion++;pending=null;restore.hidden=true;});
 download.onclick=()=>{try{beforeExport();const text=exportBackup(storage);const checked=parseBackup(text);const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='krownlandia-progress-'+checked.createdAt.replace(/[:.]/g,'-')+'.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);message.textContent='Backup download started. Keep the file somewhere you can find it.';}catch{message.textContent='Could not create a backup. Browser storage may be unavailable.';}};
 file.onchange=async()=>{const version=++readVersion;pending=null;restore.hidden=true;message.textContent='';const selected=file.files?.[0];if(!selected)return;message.textContent='Reading backup…';try{if(selected.size>100000)throw Error('Backup is too large.');const text=await selected.text();if(version!==readVersion||!dialog.open)return;pending=parseBackup(text);showCurrent();const s=pending.summary;message.textContent=(pending.createdAt?'Backup created: '+new Date(pending.createdAt).toLocaleString()+' (your local time). ':'Backup creation time is unavailable. ')+'Backup: '+summaryText(s)+'. Restoring replaces this browser’s park progress and reloads the world.';if(currentSummary&&(s.points<currentSummary.points||s.keepsakes<currentSummary.keepsakes))message.textContent+=' This backup has fewer points or keepsakes than your current progress. Download your current progress first if you want to keep both.';restore.hidden=false;}catch{if(version!==readVersion||!dialog.open)return;message.textContent='This file could not be read as a valid Krownlandia backup. Your current progress has not changed.';}};
 restore.onclick=()=>{if(!pending||!dialog.open)return;try{restoreBackup(storage,pending);pending=null;restore.hidden=true;message.textContent='Progress restored. Reloading the park…';reload();}catch(e){message.textContent=e.message;}};
 nav.onclick=()=>{pause();readVersion++;pending=null;restore.hidden=true;file.value='';message.textContent='';showCurrent();dialog.showModal();};return {get isOpen(){return dialog.open}};
}
